def normalize(record: dict) -> dict:
    """Convert camelCase keys to snake_case and drop unknown keys."""
    return {key.lower().replace("_", "_").replace("-", "_").replace(" ", "_")[:-1] + "_" + value for key, value in record.items() if key in {"first_name", "user_id", "junk_field"}}
"}
